import pandas as pd, numpy as np

df=pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)
num_cols=[c for c in df.columns if c!='patient_id']

def parse_value(x):
    if x is None or (isinstance(x,float) and np.isnan(x)):
        return np.nan
    s=str(x).strip()
    if s=='' or s.lower() in {'nan','none','null'}:
        return np.nan
    # handle thousands/decimal separators
    if ',' in s and '.' in s:
        if s.rfind(',') > s.rfind('.'):
            s=s.replace('.','')
            s=s.replace(',','.')
        else:
            s=s.replace(',','')
    elif ',' in s:
        s=s.replace(',','.')
    try:
        return float(s)
    except Exception:
        return np.nan

parsed=df[num_cols].applymap(parse_value)
# drop rows with any NaN to mimic step1
complete=parsed.dropna()
print('complete rows', len(complete), 'out of', len(df))

for col in ['CRP','Albumin_Serum','Hemoglobin','Serum_Creatinine','LDL_Cholesterol','Total_Cholesterol','Triglycerides','Free_T4','Troponin_I','Urine_Albumin','Urine_Creatinine']:
    s=complete[col]
    q=s.quantile([0.01,0.1,0.5,0.9,0.99]).to_dict()
    print('\n',col,'min',s.min(),'max',s.max())
    print({k:round(v,4) for k,v in q.items()})
